  by.forEach((o, s) => { const n = Object.keys(o).sort((a, b) => o[b] - o[a])[0]; if (!n || n === last) return; parts.push(`${SG[s]}${parts.length ? "到" : "在"}${n}`); last = n; });
  const g = ps.filter(p => p.g);
