  { const b = S.from && S.from.tagName === "IMG" ? S.from.closest(".hlc,.inp") : null; if (b && !b.closest(".lb")) S.ob = b; }   // 從精選卡片打開：看這張時空著的是那張卡片，照片牆的格子照常顯示
